{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection via Dynamic Query",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "4-8",
      "explanation": "The method concatenates the user-provided searchKey directly into a SOQL string, creating a dynamic query that can be manipulated to alter the query logic or cause errors. This allows an attacker to inject malicious SOQL fragments, potentially exposing or manipulating data.",
      "remediation": "Use a bind variable or escape the input: `String query = 'SELECT Id, Name, Industry FROM Account WHERE Name LIKE :searchKey LIMIT 50';` or `String escaped = String.escapeSingleQuotes(searchKey);` and then use `:escaped` in the query. This prevents injection while still allowing dynamic search."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Field-Level Security Not Enforced",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "4-9",
      "explanation": "The @AuraEnabled method updates the Contact.Phone field without checking field‑level security. In Apex, field permissions are not automatically enforced, so any user who can invoke the method (e.g., via a Lightning component) can modify the Phone field even if their profile or permission set does not grant edit access.",
      "remediation": "Enforce FLS by using Security.stripInaccessible on the queried record, or by running the query and DML with USER_MODE (e.g., [SELECT ...] WITH USER_MODE) or by explicitly checking hasEditAccess on the field before updating."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Record-level sharing not enforced in @AuraEnabled method",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "1-12",
      "explanation": "The class is declared without sharing, so the static SOQL query returns all Case records regardless of the current user's sharing rules. Security.stripInaccessible only removes inaccessible fields, not records, allowing users to view cases they should not see.",
      "remediation": "Declare the class with sharing (or inherited sharing) or add WITH SECURITY_ENFORCED to the SOQL query to enforce record-level sharing. This ensures only cases the user has access to are returned."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive Data Access Permissions",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "userPermissions",
      "explanation": "The permission set grants ModifyAllData and ViewAllData, giving users unrestricted access to all records, which far exceeds the intended scope of viewing and closing cases.",
      "remediation": "Remove the ModifyAllData and ViewAllData permissions from the permission set. Rely on the object-level permissions (Case read/edit) and sharing rules to enforce appropriate access."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Bypassing Record-Level Sharing",
      "severity": "High",
      "file": "ContactSearchController.cls",
      "lines": "1-10",
      "explanation": "The class is declared without sharing, so the @AuraEnabled method ignores sharing rules and can return all Contact records that match the last name, regardless of the current user's access.",
      "remediation": "Declare the class with sharing or inherited sharing, and use WITH USER_MODE or Security.stripInaccessible to enforce sharing. This ensures only records the user is allowed to see are returned."
    },
    {
      "category": "C5",
      "title": "Guest User Exposure of Sensitive Data",
      "severity": "High",
      "file": "Partner Site Profile.profile-meta.xml",
      "lines": "1-30",
      "explanation": "The Guest User profile has access to the ContactSearchController class, allowing unauthenticated users to invoke the method and retrieve Email and Phone fields for all contacts.",
      "remediation": "Remove the class from the guest profile or restrict the method to only return public data. Additionally, enforce sharing and user mode in the Apex class to prevent data leakage."
    }
  ]
}
